{"python":"import re
pdf='13048_2026_2178_MOESM1_ESM.pdf'

def val(c):
    return c.get('value','') if isinstance(c,dict) else c

def x(c):
    return c.get('x0',-999) if isinstance(c,dict) else -999

def ref(c):
    return c.get('ref','') if isinstance(c,dict) else ''

def is_num(s):
    return re.match(r'^>?\d+(?:\.\d+)?$', str(s).strip()) is not None

def numval(s):
    return float(str(s).strip().lstrip('>'))

pages=['page3','page4','page5']
truth_ranges={'page3':(430,480),'page4':(365,425),'page5':(390,440)}
records=[]
raw=[]
for page in pages:
    rows=tables[pdf][page]['rows']
    for i,row in enumerate(rows):
        org=[c for c in row if str(val(c)).startswith('Org-') and x(c)<110]
        if not org:
            continue
        org=org[0]
        lo,hi=truth_ranges[page]
        clin=None
        for j in range(max(0,i-1),min(len(rows),i+3)):
            for c in rows[j]:
                if lo<=x(c)<=hi and str(val(c)).strip().lower() in ('sensitive','resistant'):
                    clin=c
        drug_refs={}
        drug_vals={}
        for drug in ('Carboplatin','Paclitaxel'):
            drug_row=None
            for j in range(max(0,i-1),min(len(rows),i+4)):
                if any(str(val(c)).strip().lower()==drug.lower() and 180<=x(c)<=300 for c in rows[j]):
                    drug_row=rows[j]
                    break
            if drug_row is not None:
                nums=[c for c in drug_row if is_num(val(c)) and 280<=x(c)<400]
                if nums:
                    ic=max(nums,key=x)
                    drug_refs[drug]=ref(ic)
                    drug_vals[drug]=numval(val(ic))
        if clin and len(drug_refs)==2:
            oid=str(val(org)).strip()
            score_spec={'refs':[
                {'calc':'divide','args':[{'ref':drug_refs['Carboplatin']},87]},
                {'calc':'divide','args':[{'ref':drug_refs['Paclitaxel']},4.1]}
            ],'aggregate':'min'}
            truth_spec={'ref':ref(clin),'map':{'sensitive':1,'resistant':0,'Sensitive':1,'Resistant':0}}
            records.append({'id':oid,'score':score_spec,'truth':truth_spec})
            pred=min(drug_vals['Carboplatin']/87,drug_vals['Paclitaxel']/4.1)<1
            truth=str(val(clin)).strip().lower()=='sensitive'
            raw.append((oid,pred,truth,drug_vals))

correct=sum(1 for _,p,t,_ in raw if p==t)
acc=correct/len(raw) if raw else None
print('n=',len(raw),'correct=',correct,'accuracy=',acc)
for r in raw:
    print(r)

status='computed' if len(raw)==20 and abs(acc-0.8)<=0.005 else 'blocked'
